def eval_rpn(tokens: list[str]) -> int:
    stack: list[int] = []
    ops = {"+", "-", "*", "/"}

    for token in tokens:
        if token in ops:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            else:  # "/"
                q = abs(a) // abs(b)
                if (a < 0) ^ (b < 0):
                    q = -q
                stack.append(q)
        else:
            stack.append(int(token))

    return stack[0]
```

