def simplify_path(path: str) -> str:
    """
    Canonicalise an absolute Unix path.

    Handles '.', '..', repeated slashes, and removes a trailing slash
    (except for the root '/'). '...' is treated as a normal directory
    or file name, not as a parent-directory reference.
    """
    stack: list[str] = []

    for part in path.split('/'):
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return '/' + '/'.join(stack)
