def word_break(s: str, words: list[str]) -> bool:
    """Return True if s can be segmented into a sequence of words from words."""
    if not s:
        return True

    word_set = {word for word in words if word}
    if not word_set:
        return False

    lengths = {len(word) for word in word_set}
    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        for length in lengths:
            if length <= i and dp[i - length] and s[i - length:i] in word_set:
                dp[i] = True
                break

    return dp[n]
```

